pages.afterScan:
// #1598: a link to a section (cards.html#cardfile-file-card) jumps before
// the cards are built. Building them changes their height, and the browser
// can lose its place, so the jump lands hundreds of pixels off or past the
// section. Now that the visible cards are built, jump to it again.
const hashTarget = location.hash && document.getElementById(decodeURIComponent(location.hash.slice(1)));
if (hashTarget) hashTarget.scrollIntoView({ block: 'start' });

manualSections.script:
import Ajv from 'https://cdn.jsdelivr.net/npm/ajv@8.12.0/+esm';
const schemaUrl = '../../src/wb-models/label.schema.json';
const ajv = new Ajv({ strict: false });
fetch(schemaUrl).then(r => r.json()).then(schema => {
  const data = { required: false, optional: false };
  let msg;
  try {
    const valid = ajv.validate(schema, data);
    msg = valid ? 'Schema validation: PASS' : 'Schema validation: FAIL\n' + JSON.stringify(ajv.errors, null, 2);
  } catch (e) {
    msg = 'Schema validation skipped (unresolved $ref): ' + e.message;
  }
  const out = document.createElement('pre');
  out.textContent = msg;
  document.getElementById('label-schema-validation').appendChild(out);
});

// Modal padding validation
    const openDialogBtn = document.getElementById('open-dialog-btn');
    const demoDialog = document.getElementById('demo-dialog');
    const paddingWarning = document.getElementById('padding-warning');

    function hasRequiredPadding() {
      const bodyStyle = window.getComputedStyle(document.body);
      const paddingLeft = parseFloat(bodyStyle.paddingLeft);
      const paddingRight = parseFloat(bodyStyle.paddingRight);
      return paddingLeft >= 16 && paddingRight >= 16;
    }

    openDialogBtn.addEventListener('click', () => {
      if (hasRequiredPadding()) {
        paddingWarning.classList.remove('show');
        demoDialog.showModal();
      } else {
        paddingWarning.classList.add('show');
        console.warn('Modal blocked: Body requires at least 1rem padding on left and right sides.');
      }
    });
